310	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
311	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
312	        "NSW", new int[] {2000, 2099},
313	        "VIC", new int[] {3000, 3099},
314	        "QLD", new int[] {4000, 4099});
315	
316	    /**
317	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
318	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
319	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
320	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
321	     * postcode.
322	     */
323	    private boolean isPostcodeValid(Owner owner) {
324	        String postcode = owner.getPostcode();
325	        if (postcode == null || postcode.isEmpty()) {
326	            return true;
327	        }
328	        if (!postcode.matches("\\d{4}")) {
329	            return false;
330	        }
331	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
332	        if (range == null) {
333	            return true;
334	        }
335	        int value = Integer.parseInt(postcode);
336	        return value >= range[0] && value <= range[1];
337	    }
