394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
397	        HttpHeaders headers = new HttpHeaders();
398	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
399	        if (!isPostcodeValid(owner)) {
400	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
401	        }
402	        String telephone = toE164(owner.getTelephone());
403	        if (telephone == null || !hasValidNationalLength(telephone)) {
404	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
405	        }
406	        if (!normalizeEmail(owner)) {
407	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
408	        }
409	        String address = normalizeAddress(owner.getAddress());
410	        if (address.isEmpty()) {
411	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
412	        }
413	        owner.setAddress(address);
414	        owner.setTelephone(telephone);
415	        java.time.LocalDate registrationDate = toBusinessDay(
416	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
417	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
418	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
419	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
420	        }
421	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
422	            return new ResponseEntity<>(HttpStatus.CONFLICT);
423	        }
424	        List<Owner> householdMembers = householdMembers(owner);
425	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
426	        if (sharesHousehold && !householdMembers.isEmpty()) {
427	            owner.setHouseholdId(householdMembers.stream()
428	                .map(Owner::getHouseholdId)
429	                .filter(id -> id != null && !id.isBlank())
430	                .findFirst()
431	                .orElseGet(() -> householdIdFor(owner)));
432	        }
433	        // Consolidated duplicate detection: the former separate telephone, email and household
434	        // checks are now all expressed through the single derived identityKey, so a new owner is
435	        // rejected only when its WHOLE identityKey equals an existing owner's. Because the telephone
436	        // is part of the key, two members of the same household with different telephones have
437	        // different identityKeys and are both allowed.
438	        String identityKey = owner.getIdentityKey();
439	        for (Owner existing : this.clinicService.findAllOwners()) {
440	            if (identityKey.equals(existing.getIdentityKey())) {
441	                return new ResponseEntity<>(HttpStatus.CONFLICT);
442	            }
443	        }
444	        if (owner.getHouseholdId() != null) {
445	            for (Owner member : householdMembers) {
446	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
447	                    member.setHouseholdId(owner.getHouseholdId());
448	                    this.clinicService.saveOwner(member);
449	                }
450	            }
451	        }
452	        owner.setNamesakeCount(namesakeCount(owner));
453	        owner.setHouseholdSize(householdMembers.size() + 1);
454	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
455	        owner.setRegistrationDate(registrationDate);
456	        owner.setCustomerCode(customerCodeFor(owner));
457	        this.clinicService.saveOwner(owner);
458	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
459	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
460	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
461	        headers.setLocation(UriComponentsBuilder.newInstance()
462	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
463	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
464	    }
